CREATE TABLE public.account_snapshots (
	id int8 GENERATED ALWAYS AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL,
	account_type text NOT NULL,
	login int8 NULL,
	asset text NULL,
	balance numeric NULL,
	equity numeric NULL,
	margin numeric NULL,
	margin_level numeric NULL,
	floating_pl numeric NULL,
	peak_equity numeric NULL,
	drawdown_pct numeric NULL,
	day_loss_pct numeric NULL,
	consecutive_losses int4 NULL,
	consecutive_wins int4 NULL,
	risk_cooldown_active bool NULL,
	drawdown_halt bool NULL,
	ts timestamptz DEFAULT now() NOT NULL,
	CONSTRAINT account_snapshots_account_type_not_null NOT NULL account_type,
	CONSTRAINT account_snapshots_id_not_null NOT NULL id,
	CONSTRAINT account_snapshots_pkey PRIMARY KEY (id),
	CONSTRAINT account_snapshots_ts_not_null NOT NULL ts
);

CREATE TABLE public.forecasts (
	id bigserial NOT NULL,
	asset varchar(20) NOT NULL,
	generated_at timestamptz DEFAULT now() NOT NULL,
	horizon_minutes int4 DEFAULT 30 NOT NULL,
	bullish_prob numeric(5, 2) NULL,
	bearish_prob numeric(5, 2) NULL,
	suggested_sl_atr_mult numeric(5, 2) NULL,
	suggested_tp_atr_mult numeric(5, 2) NULL,
	rationale text NULL,
	model_used varchar(50) NULL,
	direction varchar(16) NULL,
	confidence numeric(5, 2) NULL,
	CONSTRAINT forecasts_asset_not_null NOT NULL asset,
	CONSTRAINT forecasts_bearish_prob_check CHECK (((bearish_prob >= 0.0) AND (bearish_prob <= 100.0))),
	CONSTRAINT forecasts_bullish_prob_check CHECK (((bullish_prob >= 0.0) AND (bullish_prob <= 100.0))),
	CONSTRAINT forecasts_generated_at_not_null NOT NULL generated_at,
	CONSTRAINT forecasts_horizon_minutes_not_null NOT NULL horizon_minutes,
	CONSTRAINT forecasts_id_not_null NOT NULL id,
	CONSTRAINT forecasts_pkey PRIMARY KEY (id)
);

CREATE TABLE public.missed_trade_analytics (
	id serial4 NOT NULL,
	asset varchar(20) NOT NULL,
	groq_analysis text NULL,
	suggested_logic_tweak text NULL,
	analyzed_at timestamptz DEFAULT now() NULL,
	created_at timestamptz DEFAULT now() NULL,
	CONSTRAINT missed_trade_analytics_asset_not_null NOT NULL asset,
	CONSTRAINT missed_trade_analytics_id_not_null NOT NULL id,
	CONSTRAINT missed_trade_analytics_pkey PRIMARY KEY (id)
);

CREATE TABLE public.missed_trade_signals (
	id int8 GENERATED ALWAYS AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL,
	asset text NOT NULL,
	account_type text NULL,
	reason text NOT NULL,
	side text NOT NULL,
	score numeric NULL,
	raw_score numeric NULL,
	threshold numeric NULL,
	rsi numeric NULL,
	price numeric NULL,
	atr numeric NULL,
	sl_distance numeric NULL,
	tp_distance numeric NULL,
	tier2_action text NULL,
	tier2_confidence numeric NULL,
	session_hour int4 NULL,
	magic_number int8 NULL,
	created_at timestamptz DEFAULT now() NOT NULL,
	evaluated bool DEFAULT false NOT NULL,
	evaluated_at timestamptz NULL,
	outcome text NULL,
	simulated_pnl_r numeric NULL,
	CONSTRAINT missed_trade_signals_asset_not_null NOT NULL asset,
	CONSTRAINT missed_trade_signals_created_at_not_null NOT NULL created_at,
	CONSTRAINT missed_trade_signals_evaluated_not_null NOT NULL evaluated,
	CONSTRAINT missed_trade_signals_id_not_null NOT NULL id,
	CONSTRAINT missed_trade_signals_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['would_have_won'::text, 'would_have_lost'::text, 'inconclusive'::text])))),
	CONSTRAINT missed_trade_signals_pkey PRIMARY KEY (id),
	CONSTRAINT missed_trade_signals_reason_not_null NOT NULL reason,
	CONSTRAINT missed_trade_signals_rsi_check CHECK (((rsi IS NULL) OR ((rsi >= (0)::numeric) AND (rsi <= (100)::numeric)))),
	CONSTRAINT missed_trade_signals_side_check CHECK ((side = ANY (ARRAY['BUY'::text, 'SELL'::text]))),
	CONSTRAINT missed_trade_signals_side_not_null NOT NULL side,
	CONSTRAINT missed_trade_signals_tier2_confidence_check CHECK (((tier2_confidence IS NULL) OR ((tier2_confidence >= (0)::numeric) AND (tier2_confidence <= (1)::numeric))))
);

CREATE TABLE public.optimization_logs (
	id serial4 NOT NULL,
	asset varchar(20) NOT NULL,
	timeframe varchar(10) NOT NULL,
	pass_number int4 NULL,
	profit numeric NULL,
	total_trades int4 NULL,
	win_rate numeric NULL,
	drawdown numeric NULL,
	parameters jsonb NULL,
	tested_at timestamptz DEFAULT now() NULL,
	CONSTRAINT optimization_logs_asset_not_null NOT NULL asset,
	CONSTRAINT optimization_logs_id_not_null NOT NULL id,
	CONSTRAINT optimization_logs_pkey PRIMARY KEY (id),
	CONSTRAINT optimization_logs_timeframe_not_null NOT NULL timeframe
);

CREATE TABLE public.risk_incidents (
	id int8 GENERATED ALWAYS AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL,
	account_type text NOT NULL,
	asset text NULL,
	reason text NOT NULL,
	details text NULL,
	created_at timestamptz DEFAULT now() NOT NULL,
	CONSTRAINT risk_incidents_account_type_not_null NOT NULL account_type,
	CONSTRAINT risk_incidents_created_at_not_null NOT NULL created_at,
	CONSTRAINT risk_incidents_id_not_null NOT NULL id,
	CONSTRAINT risk_incidents_pkey PRIMARY KEY (id),
	CONSTRAINT risk_incidents_reason_not_null NOT NULL reason
);

CREATE TABLE public.strategy_db (
	asset text NOT NULL,
	opt_threshold numeric NULL,
	opt_sl_mult numeric NULL,
	opt_tp_mult numeric NULL,
	scheduled_start_hour int4 NULL,
	scheduled_end_hour int4 NULL,
	live_approved bool DEFAULT false NOT NULL,
	updated_at timestamptz DEFAULT now() NULL,
	win_rate numeric NULL,
	profit_factor numeric NULL,
	sample_size int4 NULL,
	rsi_buy_max numeric(5, 2) DEFAULT 70.0 NULL,
	rsi_sell_min numeric(5, 2) DEFAULT 30.0 NULL,
	calibration_score numeric NULL,
	calibration_n int4 NULL,
	calibration_updated_at timestamptz NULL,
	CONSTRAINT chk_opt_sl CHECK (((opt_sl_mult >= 0.5) AND (opt_sl_mult <= 5.0))),
	CONSTRAINT chk_opt_threshold CHECK (((opt_threshold >= 0.10) AND (opt_threshold <= 0.90))),
	CONSTRAINT chk_opt_tp CHECK (((opt_tp_mult >= 0.5) AND (opt_tp_mult <= 10.0))),
	CONSTRAINT strategy_db_asset_not_null NOT NULL asset,
	CONSTRAINT strategy_db_asset_pk PRIMARY KEY (asset),
	CONSTRAINT strategy_db_asset_unique UNIQUE (asset),
	CONSTRAINT strategy_db_live_approved_not_null NOT NULL live_approved
);

CREATE TABLE public.telemetry (
	forecast_id varchar(255) NOT NULL,
	symbol varchar(20) NOT NULL,
	"action" varchar(50) NULL,
	confidence numeric(5, 4) NULL,
	pnl numeric(10, 4) NULL,
	brier_score numeric(5, 4) NULL,
	"timestamp" timestamptz DEFAULT now() NOT NULL,
	CONSTRAINT telemetry_forecast_id_not_null NOT NULL forecast_id,
	CONSTRAINT telemetry_pkey PRIMARY KEY (forecast_id),
	CONSTRAINT telemetry_symbol_not_null NOT NULL symbol,
	CONSTRAINT telemetry_timestamp_not_null NOT NULL "timestamp"
);

CREATE TABLE public.tick_telemetry (
	id bigserial NOT NULL,
	asset varchar(20) NOT NULL,
	ts timestamptz DEFAULT now() NOT NULL,
	bid numeric(18, 5) NULL,
	ask numeric(18, 5) NULL,
	tick_volume int4 NULL,
	rsi numeric(6, 2) NULL,
	tema numeric(18, 5) NULL,
	ac numeric(18, 5) NULL,
	sar numeric(18, 5) NULL,
	adx numeric(6, 2) NULL,
	ma10 numeric(18, 5) NULL,
	ma20 numeric(18, 5) NULL,
	ma50 numeric(18, 5) NULL,
	ma100 numeric(18, 5) NULL,
	ma200 numeric(18, 5) NULL,
	CONSTRAINT tick_telemetry_adx_check CHECK (((adx >= (0)::numeric) AND (adx <= (100)::numeric))),
	CONSTRAINT tick_telemetry_asset_not_null NOT NULL asset,
	CONSTRAINT tick_telemetry_id_not_null NOT NULL id,
	CONSTRAINT tick_telemetry_pkey PRIMARY KEY (id),
	CONSTRAINT tick_telemetry_rsi_check CHECK (((rsi >= (0)::numeric) AND (rsi <= (100)::numeric))),
	CONSTRAINT tick_telemetry_ts_not_null NOT NULL ts
);

CREATE TABLE public.trading_assets (
	asset_id uuid DEFAULT gen_random_uuid() NOT NULL,
	symbol varchar(15) NOT NULL,
	asset_class varchar(50) NOT NULL,
	pip_size numeric(10, 5) NOT NULL,
	tick_size numeric(10, 5) NOT NULL,
	contract_size int4 DEFAULT 100000 NOT NULL,
	is_active bool DEFAULT true NULL,
	created_at timestamptz DEFAULT now() NULL,
	updated_at timestamptz DEFAULT now() NULL,
	pip_value numeric NULL,
	CONSTRAINT trading_assets_asset_class_not_null NOT NULL asset_class,
	CONSTRAINT trading_assets_asset_id_not_null NOT NULL asset_id,
	CONSTRAINT trading_assets_contract_size_not_null NOT NULL contract_size,
	CONSTRAINT trading_assets_pip_size_not_null NOT NULL pip_size,
	CONSTRAINT trading_assets_pkey PRIMARY KEY (asset_id),
	CONSTRAINT trading_assets_symbol_key UNIQUE (symbol),
	CONSTRAINT trading_assets_symbol_not_null NOT NULL symbol,
	CONSTRAINT trading_assets_tick_size_not_null NOT NULL tick_size
);

CREATE TABLE public.autotune_log (
	id int8 GENERATED ALWAYS AS IDENTITY( INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 CACHE 1 NO CYCLE) NOT NULL,
	asset text NOT NULL,
	win_rate numeric NULL,
	profit_factor numeric NULL,
	sample_size int4 NULL,
	old_threshold numeric NULL,
	new_threshold numeric NULL,
	old_sl numeric NULL,
	new_sl numeric NULL,
	old_tp numeric NULL,
	new_tp numeric NULL,
	ts timestamptz DEFAULT now() NOT NULL,
	CONSTRAINT autotune_log_asset_not_null NOT NULL asset,
	CONSTRAINT autotune_log_id_not_null NOT NULL id,
	CONSTRAINT autotune_log_pkey PRIMARY KEY (id),
	CONSTRAINT autotune_log_ts_not_null NOT NULL ts,
	CONSTRAINT fk_autotune_log_asset FOREIGN KEY (asset) REFERENCES public.strategy_db(asset) ON DELETE CASCADE
);

CREATE TABLE public.strategy_lifeline (
	asset text NOT NULL,
	lifeline_score numeric DEFAULT 100.0 NOT NULL,
	win_streak int4 DEFAULT 0 NOT NULL,
	loss_streak int4 DEFAULT 0 NOT NULL,
	last_delta numeric NULL,
	terminated bool DEFAULT false NOT NULL,
	terminated_at timestamptz NULL,
	updated_at timestamptz DEFAULT now() NOT NULL,
	CONSTRAINT strategy_lifeline_asset_not_null NOT NULL asset,
	CONSTRAINT strategy_lifeline_lifeline_score_check CHECK (((lifeline_score >= 0.0) AND (lifeline_score <= 200.0))),
	CONSTRAINT strategy_lifeline_lifeline_score_not_null NOT NULL lifeline_score,
	CONSTRAINT strategy_lifeline_loss_streak_not_null NOT NULL loss_streak,
	CONSTRAINT strategy_lifeline_pkey PRIMARY KEY (asset),
	CONSTRAINT strategy_lifeline_terminated_not_null NOT NULL terminated,
	CONSTRAINT strategy_lifeline_updated_at_not_null NOT NULL updated_at,
	CONSTRAINT strategy_lifeline_win_streak_not_null NOT NULL win_streak,
	CONSTRAINT strategy_lifeline_asset_fkey FOREIGN KEY (asset) REFERENCES public.strategy_db(asset) ON DELETE CASCADE
);

CREATE TABLE public.trade_telemetry (
	id bigserial NOT NULL,
	asset text NOT NULL,
	"type" text NOT NULL,
	price numeric NULL,
	lots numeric(10, 2) NULL,
	profit numeric NULL,
	created_at timestamptz DEFAULT now() NOT NULL,
	rsi numeric NULL,
	entry_score numeric NULL,
	sl_price numeric NULL,
	tp_price numeric NULL,
	magic_number int8 NULL,
	account_type text NULL,
	session_hour int4 NULL,
	forecast_id int8 NULL,
	tier2_confidence numeric NULL,
	micro_trend varchar(10) DEFAULT 'NEUTRAL'::character varying NULL,
	reward_utility numeric NULL,
	entry_features jsonb NULL,
	entry_e_utility float8 NULL,
	CONSTRAINT trade_telemetry_asset_not_null NOT NULL asset,
	CONSTRAINT trade_telemetry_created_at_not_null NOT NULL created_at,
	CONSTRAINT trade_telemetry_id_not_null NOT NULL id,
	CONSTRAINT trade_telemetry_pkey PRIMARY KEY (id),
	CONSTRAINT trade_telemetry_type_not_null NOT NULL type,
	CONSTRAINT fk_trade_telemetry_forecast FOREIGN KEY (forecast_id) REFERENCES public.forecasts(id)
);

CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
